  `payroll_id`         INT           NOT NULL,
  `benefit_type_id`    INT           NOT NULL,
  `amount`             DECIMAL(15,2) NOT NULL,
  `created_at`         DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`         DATETIME      NULL ON UPDATE CURRENT_TIMESTAMP,
  `created_by`         INT           NULL,
  `updated_by`         INT           NULL,
  PRIMARY KEY (`payroll_benefit_id`),
  UNIQUE KEY `uq_payroll_benefit` (`payroll_id`,`benefit_type_id`),
  KEY `idx_payroll_benefit_payroll` (`payroll_id`),
  KEY `idx_payroll_benefit_type` (`benefit_type_id`),
  CONSTRAINT `fk_payroll_benefit_payroll` FOREIGN KEY (`payroll_id`) REFERENCES `payroll` (`payroll_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_payroll_benefit_type` FOREIGN KEY (`benefit_type_id`) REFERENCES `benefit_type` (`benefit_type_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB;

DROP TABLE IF EXISTS `payroll_deduction`;

CREATE TABLE `payroll_deduction` (
  `payroll_deduction_id` INT           NOT NULL AUTO_INCREMENT,
  `payroll_id`           INT           NOT NULL,
  `deduction_type_id`    INT           NOT NULL,
  `amount`               DECIMAL(15,2) NOT NULL,
  `created_at`           DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`           DATETIME      NULL ON UPDATE CURRENT_TIMESTAMP,
  `created_by`           INT           NULL,
  `updated_by`           INT           NULL,
  PRIMARY KEY (`payroll_deduction_id`),
  UNIQUE KEY `uq_payroll_deduction` (`payroll_id`,`deduction_type_id`),
  KEY `idx_payroll_deduction_payroll` (`payroll_id`),
  KEY `idx_payroll_deduction_type` (`deduction_type_id`),
  CONSTRAINT `fk_payroll_deduction_payroll` FOREIGN KEY (`payroll_id`) REFERENCES `payroll` (`payroll_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_payroll_deduction_type` FOREIGN KEY (`deduction_type_id`) REFERENCES `deduction_type` (`deduction_type_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB;

DROP TABLE IF EXISTS `payslip`;

CREATE TABLE `payslip` (
  `payslip_id`     INT         NOT NULL AUTO_INCREMENT,
  `payroll_id`     INT         NOT NULL,
  `payslip_number` VARCHAR(50) NOT NULL,
  `generated_at`   DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'when the physical PDF document was generated/saved',
  `generated_by`   INT         NULL COMMENT 'employee_id of who triggered the PDF generation',
  `created_at`     DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'when the payslip record was created in the system',
  `updated_at`     DATETIME    NULL ON UPDATE CURRENT_TIMESTAMP,
  `created_by`     INT         NULL,
  `updated_by`     INT         NULL,
  PRIMARY KEY (`payslip_id`),
  UNIQUE KEY `uq_payslip_payroll` (`payroll_id`),
  UNIQUE KEY `uq_payslip_number` (`payslip_number`),
  CONSTRAINT `fk_payslip_payroll` FOREIGN KEY (`payroll_id`) REFERENCES `payroll` (`payroll_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB;

DROP TABLE IF EXISTS `help_center_ticket`;

CREATE TABLE `help_center_ticket` (
  `ticket_id`               INT      NOT NULL AUTO_INCREMENT,
  `employee_id`             INT      NOT NULL,
  `help_center_category_id` INT      NOT NULL,
  `issue`                   TEXT     NOT NULL,
  `request_status_id`       INT      NOT NULL,
  `created_at`              DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`              DATETIME NULL ON UPDATE CURRENT_TIMESTAMP,
  `created_by`              INT      NULL,
  `updated_by`              INT      NULL,
  PRIMARY KEY (`ticket_id`),
  KEY `idx_ticket_employee` (`employee_id`),
  KEY `idx_ticket_category` (`help_center_category_id`),
  KEY `idx_ticket_status` (`request_status_id`),
  CONSTRAINT `fk_ticket_employee` FOREIGN KEY (`employee_id`) REFERENCES `employee` (`employee_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ticket_category` FOREIGN KEY (`help_center_category_id`) REFERENCES `help_center_category` (`help_center_category_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ticket_status` FOREIGN KEY (`request_status_id`) REFERENCES `request_status` (`request_status_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB;

DROP TABLE IF EXISTS `approval`;

CREATE TABLE `approval` (
  `approval_id`       INT         NOT NULL AUTO_INCREMENT,
  `request_type`      VARCHAR(50) NOT NULL COMMENT 'leave_request | work_time_request',
  `request_id`        INT         NOT NULL,
  `approver_id`       INT         NOT NULL,
  `request_status_id` INT         NOT NULL,
  `remarks`           TEXT        NULL,
  `approved_at`       DATETIME    NULL,
  `created_at`        DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`        DATETIME    NULL ON UPDATE CURRENT_TIMESTAMP,
  `created_by`        INT         NULL,
  `updated_by`        INT         NULL,
  PRIMARY KEY (`approval_id`),
  KEY `idx_approval_request` (`request_type`,`request_id`),
  KEY `idx_approval_approver` (`approver_id`),
  KEY `idx_approval_status` (`request_status_id`),
  CONSTRAINT `fk_approval_approver` FOREIGN KEY (`approver_id`) REFERENCES `employee` (`employee_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_approval_status` FOREIGN KEY (`request_status_id`) REFERENCES `request_status` (`request_status_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB;

DROP TABLE IF EXISTS `action_log`;

CREATE TABLE `action_log` (
  `action_log_id`   INT          NOT NULL AUTO_INCREMENT,
  `user_account_id` INT          NOT NULL,
  `action_name`     VARCHAR(255) NOT NULL,
  `table_name`      VARCHAR(100) NOT NULL,
  `record_id`       INT          NOT NULL,
  `old_value`       TEXT         NULL,
  `new_value`       TEXT         NULL,
  `created_at`      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by`      INT          NULL,
  `updated_by`      INT          NULL,
  PRIMARY KEY (`action_log_id`),
  KEY `idx_action_log_user` (`user_account_id`),
  KEY `idx_action_log_table_record` (`table_name`,`record_id`),
  CONSTRAINT `fk_action_log_user` FOREIGN KEY (`user_account_id`) REFERENCES `user_account` (`user_account_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB;

-- -------------------------------------------------------------
-- VIEW 3: v_pending_requests
-- All unapproved leave and work-time requests in one list.
-- Useful for a manager's approval dashboard — shows who
-- requested what, when, and what type it is.
-- -------------------------------------------------------------
DROP VIEW IF EXISTS `v_pending_requests`;
CREATE VIEW `v_pending_requests` AS

SELECT
    'leave'                                AS request_category,
    lr.leave_request_id                    AS request_id,
    e.employee_id,
    CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
    lt.leave_type_name                     AS request_type,
    lr.start_date                          AS request_date,
    NULL                                   AS start_time,
    NULL                                   AS end_time,
    lr.description                         AS reason,
    rs.request_status_type                 AS status
FROM leave_request lr
JOIN employee        e   ON lr.employee_id        = e.employee_id
JOIN leave_type      lt  ON lr.leave_type_id      = lt.leave_type_id
JOIN request_status  rs  ON lr.request_status_id  = rs.request_status_id
WHERE rs.request_status_type = 'Pending'

UNION ALL

SELECT
    'work_time'                            AS request_category,
    wtr.work_time_request_id               AS request_id,
    e.employee_id,
    CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
    wtr.request_type                       AS request_type,
    wtr.request_date,
    wtr.start_time,
    wtr.end_time,
    wtr.reason,
    rs.request_status_type                 AS status
FROM work_time_request wtr
JOIN employee        e   ON wtr.employee_id       = e.employee_id
JOIN request_status  rs  ON wtr.request_status_id = rs.request_status_id
WHERE rs.request_status_type = 'Pending'

ORDER BY request_date ASC;


-- -------------------------------------------------------------
-- VIEW 4: v_attendance_summary
-- Total hours worked per employee per month.
-- Used for payroll computation — feed this into your Java
-- payroll calculator to get hours_worked for the pay period.
-- -------------------------------------------------------------
DROP VIEW IF EXISTS `v_attendance_summary`;
CREATE VIEW `v_attendance_summary` AS
SELECT
    e.employee_id,
    CONCAT(e.first_name, ' ', e.last_name) AS full_name,
    YEAR(a.attendance_date)                AS work_year,
    MONTH(a.attendance_date)               AS work_month,
    COUNT(a.attendance_id)                 AS days_present,
    ROUND(
        SUM(
            TIMESTAMPDIFF(MINUTE, a.time_in, a.time_out) / 60.0
        ), 2
    )                                      AS total_hours_worked
FROM attendance a
JOIN employee e ON a.employee_id = e.employee_id
WHERE a.time_in IS NOT NULL
  AND a.time_out IS NOT NULL
GROUP BY
    e.employee_id, e.first_name, e.last_name,
    YEAR(a.attendance_date), MONTH(a.attendance_date)
ORDER BY e.employee_id, work_year, work_month;


-- =============================================================================
-- VIEW 5: v_user_account
-- Flattens user_account + account_role + user_role into one row per user.
-- When a user has multiple roles the highest-privilege role is kept
-- (lowest role_id = most privileged, matching seed data order).
-- Add this block to MotorPH_Payroll_Database_modified_with_views.sql
-- just before the closing SET statements, alongside the other views.
-- =============================================================================
 
DROP VIEW IF EXISTS `v_user_account`;
CREATE VIEW `v_user_account` AS
SELECT
    ua.user_account_id,
    ua.employee_id,
    ua.username,
    ua.password_hash,
    ua.is_active,
    -- Pick the highest-privilege role (smallest role_id)
    r.role_id,
    r.role_name
FROM user_account ua
-- Subquery finds the most-privileged role_id for each account
LEFT JOIN account_role ar ON ar.user_account_id = ua.user_account_id
                          AND ar.role_id = (
                              SELECT MIN(ar2.role_id)
                              FROM account_role ar2
                              WHERE ar2.user_account_id = ua.user_account_id
                          )
LEFT JOIN user_role r ON r.role_id = ar.role_id;


-- -------------------------------------------------------------
-- VIEW 6: v_payslip_detail
-- One row per generated payslip, with everything the Payslip
-- model needs already joined and the per-type benefits/deductions
-- pivoted into columns (rice subsidy, phone allowance, clothing
-- allowance, SSS, PhilHealth, Pag-IBIG, withholding tax).
--
-- benefit_type_id mapping:  1 = Rice Subsidy, 2 = Phone Allowance, 3 = Clothing Allowance
-- deduction_type_id mapping: 1 = SSS, 2 = PhilHealth, 3 = Pag-IBIG, 4 = Withholding Tax
-- (see seed data for `benefit_type` / `deduction_type`)
-- -------------------------------------------------------------
DROP VIEW IF EXISTS `v_payslip_detail`;
CREATE VIEW `v_payslip_detail` AS
SELECT
    ps.payslip_id,
    ps.payslip_number,
    ps.generated_at,
    pr.payroll_id,
    e.employee_id,
    CONCAT(e.first_name, ' ', e.last_name)   AS full_name,
    p.position_name,
    pp.period_start_date,
    pp.period_end_date,
    pr.hours_worked,
    pr.hourly_rate,
    pr.gross_pay,
    pr.net_pay,
    COALESCE(MAX(CASE WHEN pb.benefit_type_id   = 1 THEN pb.amount END), 0) AS rice_subsidy,
    COALESCE(MAX(CASE WHEN pb.benefit_type_id   = 2 THEN pb.amount END), 0) AS phone_allowance,
    COALESCE(MAX(CASE WHEN pb.benefit_type_id   = 3 THEN pb.amount END), 0) AS clothing_allowance,
    COALESCE(MAX(CASE WHEN pd.deduction_type_id = 1 THEN pd.amount END), 0) AS sss,
    COALESCE(MAX(CASE WHEN pd.deduction_type_id = 2 THEN pd.amount END), 0) AS philhealth,
    COALESCE(MAX(CASE WHEN pd.deduction_type_id = 3 THEN pd.amount END), 0) AS pagibig,
    COALESCE(MAX(CASE WHEN pd.deduction_type_id = 4 THEN pd.amount END), 0) AS withholding_tax
FROM payslip ps
JOIN payroll          pr ON ps.payroll_id     = pr.payroll_id
JOIN employee          e ON pr.employee_id    = e.employee_id
JOIN pay_period        pp ON pr.pay_period_id = pp.pay_period_id
LEFT JOIN employee_position p ON e.position_id = p.position_id
LEFT JOIN payroll_benefit   pb ON pr.payroll_id = pb.payroll_id
LEFT JOIN payroll_deduction pd ON pr.payroll_id = pd.payroll_id
GROUP BY
    ps.payslip_id, ps.payslip_number, ps.generated_at,
    pr.payroll_id, e.employee_id, e.first_name, e.last_name,
    p.position_name, pp.period_start_date, pp.period_end_date,
    pr.hours_worked, pr.hourly_rate, pr.gross_pay, pr.net_pay;


-- -------------------------------------------------------------
-- VIEW 7: v_leave_requests
-- Flat view of all leave requests with resolved status name,
-- leave type name, employee name, and approver name.
-- Used by JdbcRequestDAO and approval screens.
-- -------------------------------------------------------------
DROP VIEW IF EXISTS `v_leave_requests`;
CREATE VIEW `v_leave_requests` AS
SELECT
    lr.leave_request_id,
    lr.employee_id,
    CONCAT(e.first_name, ' ', e.last_name)    AS employee_name,
    lt.leave_type_id,
    lt.leave_type_name,
    lr.start_date,
    lr.end_date,
    lr.description,
    lr.request_status_id,
    rs.request_status_type,
    lr.approved_by,
    CONCAT(ap.first_name, ' ', ap.last_name)  AS approver_name,
    lr.approved_at,
    lr.created_at
FROM leave_request lr
JOIN employee        e   ON lr.employee_id       = e.employee_id
JOIN leave_type      lt  ON lr.leave_type_id     = lt.leave_type_id
JOIN request_status  rs  ON lr.request_status_id = rs.request_status_id
LEFT JOIN employee   ap  ON lr.approved_by       = ap.employee_id;


-- -------------------------------------------------------------
-- VIEW 8: v_work_time_requests
-- Flat view of all overtime and undertime requests with resolved
-- status name, employee name, approver name, and computed hours.
-- Used by JdbcRequestDAO and approval screens.
-- -------------------------------------------------------------
DROP VIEW IF EXISTS `v_work_time_requests`;
CREATE VIEW `v_work_time_requests` AS
SELECT
    wtr.work_time_request_id,
    wtr.employee_id,
    CONCAT(e.first_name, ' ', e.last_name)   AS employee_name,
    wtr.request_type,
    wtr.request_date,
    wtr.start_time,
    wtr.end_time,
    ROUND(TIMESTAMPDIFF(MINUTE, wtr.start_time, wtr.end_time) / 60.0, 2) AS hours,
    wtr.reason,
    wtr.request_status_id,
    rs.request_status_type,
    wtr.approved_by,
    CONCAT(ap.first_name, ' ', ap.last_name) AS approver_name,
    wtr.approved_at,
    wtr.created_at
FROM work_time_request wtr
JOIN employee        e   ON wtr.employee_id       = e.employee_id
JOIN request_status  rs  ON wtr.request_status_id = rs.request_status_id
LEFT JOIN employee   ap  ON wtr.approved_by       = ap.employee_id;


