-- =============================================================================
-- DISPUTE TABLE
-- Covers both InformationDispute (category + target_field) and
-- PayrollDispute (payslip_number).  The dispute_type column is the
-- discriminator so both subtypes live in one table.
-- =============================================================================

DROP TABLE IF EXISTS `dispute`;
CREATE TABLE `dispute` (
  `dispute_id`      INT          NOT NULL AUTO_INCREMENT,
  `employee_id`     INT          NOT NULL,
  `dispute_type`    ENUM('INFORMATION_DISPUTE','PAYROLL_DISPUTE') NOT NULL,
  `reason`          TEXT         NOT NULL,
  `dispute_status`  ENUM('UNRESOLVED','RESOLVED') NOT NULL DEFAULT 'UNRESOLVED',
  `reviewed_by_id`  INT          NULL,
  `date_filed`      DATE         NOT NULL DEFAULT (CURDATE()),
  `date_reviewed`   DATE         NULL,
  -- InformationDispute columns (NULL for PayrollDispute rows)
  `category`        VARCHAR(100) NULL,
  `target_field`    VARCHAR(100) NULL,
  -- PayrollDispute column (NULL for InformationDispute rows)
  `payslip_number`  VARCHAR(50)  NULL,
  `created_at`      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`      DATETIME     NULL ON UPDATE CURRENT_TIMESTAMP,
  `created_by`      INT          NULL,
  `updated_by`      INT          NULL,
  PRIMARY KEY (`dispute_id`),
  KEY `idx_dispute_employee`  (`employee_id`),
  KEY `idx_dispute_status`    (`dispute_status`),
  CONSTRAINT `fk_dispute_employee`    FOREIGN KEY (`employee_id`)    REFERENCES `employee` (`employee_id`) ON DELETE CASCADE  ON UPDATE CASCADE,
  CONSTRAINT `fk_dispute_reviewed_by` FOREIGN KEY (`reviewed_by_id`) REFERENCES `employee` (`employee_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB;


-- -------------------------------------------------------------
-- VIEW: v_dispute
-- Joins employee names for display; used by JdbcDisputeDAO reads.
-- -------------------------------------------------------------
DROP VIEW IF EXISTS `v_dispute`;
CREATE VIEW `v_dispute` AS
SELECT
    d.dispute_id,
    d.employee_id,
    CONCAT(e.first_name, ' ', e.last_name)  AS employee_name,
    d.dispute_type,
    d.reason,
    d.dispute_status,
    d.reviewed_by_id,
    CONCAT(r.first_name, ' ', r.last_name)  AS reviewer_name,
    d.date_filed,
    d.date_reviewed,
    d.category,
    d.target_field,
    d.payslip_number,
    d.created_at
FROM dispute d
JOIN  employee e ON d.employee_id    = e.employee_id
LEFT JOIN employee r ON d.reviewed_by_id = r.employee_id;


